(
    'cybersecurity', 'vulnerability-assessment', 1, 'Vulnerability Assessment', 'Find and prioritize weaknesses across the estate.',
    'A scoped review of systems, identities, endpoints, networks and cloud assets, with findings validated and ranked by business risk.', 'A vulnerability assessment gives the team an actionable view of exposure without treating every scan result as equally urgent. We confirm what is reachable, check findings against the operating context, and turn the result into a remediation plan with owners and priorities.', '[{"title":"Scope and asset discovery","body":"Confirm the authorized systems, environments and testing windows; identify assets that are missing from the current inventory."},{"title":"Vulnerability discovery","body":"Review known software, configuration and exposure weaknesses across the approved estate."},{"title":"Validation and prioritization","body":"Remove false positives and rank verified findings by exploitability, exposure and business impact."},{"title":"Remediation plan","body":"Provide clear actions, owners and suggested sequencing, then validate fixes when requested."}]'::jsonb, array(select jsonb_array_elements_text('["Verified findings rather than an unfiltered scan dump","Risk-ranked remediation priorities","Clear ownership for corrective action"]'::jsonb))::text[],
    '[{"question":"How is a vulnerability assessment different from a penetration test?","answer":"A vulnerability assessment identifies and prioritizes weaknesses across an agreed scope. A penetration test goes further by safely attempting to exploit selected weaknesses to demonstrate real attack paths."},{"question":"Will testing disrupt production systems?","answer":"The scope and testing method are agreed first. Checks are selected and scheduled to avoid unsafe activity, and intrusive validation is only performed when explicitly authorized."},{"question":"Do you provide remediation?","answer":"Yes. Findings are translated into practical remediation steps, and fixes can be rechecked to confirm the exposure has been reduced."}]'::jsonb, null, '{"seed":201,"label":"Vulnerability assessment","caption":"An authorized assessment maps exposed systems and prioritizes verified weaknesses for remediation."}'::jsonb,
    'Vulnerability Assessment Services', 'Scoped vulnerability assessment, validated findings and risk-ranked remediation plans for business IT environments.', 'published', null
  ),
(
    'cybersecurity', 'penetration-testing', 2, 'Penetration Testing', 'Test defenses through controlled, authorized attack simulation.',
    'A rules-of-engagement-led test of selected applications, infrastructure or external attack surfaces, followed by evidence, remediation guidance and retesting.', 'Penetration testing evaluates whether an attacker can chain weaknesses into meaningful access or impact. Every engagement starts with written authorization, agreed boundaries, safety controls and a clear plan for handling critical findings.', '[{"title":"Rules of engagement","body":"Define systems, techniques, test windows, emergency contacts, prohibited actions and evidence handling before testing begins."},{"title":"Controlled security testing","body":"Assess the agreed application, network or external surface using safe, scoped techniques that reflect realistic attack paths."},{"title":"Evidence-backed report","body":"Document verified findings, impact, reproduction context and actionable remediation without unnecessary exposure of sensitive data."},{"title":"Retest and closure","body":"Validate agreed fixes and record residual risks or follow-up actions."}]'::jsonb, array(select jsonb_array_elements_text('["Demonstrated attack paths within an approved scope","Evidence linked to business impact","Practical fixes and optional retesting"]'::jsonb))::text[],
    '[{"question":"Do you test production systems?","answer":"Only when the client explicitly authorizes it and suitable safeguards are agreed. Testing scope, timing, emergency contacts and prohibited actions are documented before work starts."},{"question":"What does a penetration test report include?","answer":"A report includes the approved scope, verified findings, evidence, impact, remediation guidance and any agreed retest results."},{"question":"Can you retest after remediation?","answer":"Yes. Retesting confirms whether the agreed fixes address the original findings and records any remaining exposure."}]'::jsonb, null, '{"seed":202,"label":"Penetration testing","caption":"A controlled test follows written authorization and rules of engagement to validate real attack paths safely."}'::jsonb,
    'Penetration Testing Services', 'Authorized, scoped penetration testing with evidence-backed findings, remediation guidance and optional retesting.', 'published', null
  ),
(
    'cybersecurity', 'threat-modeling', 3, 'Threat Modeling', 'Anticipate how a system could be attacked before it goes live.',
    'Structured analysis of architecture, trust boundaries, data flows and misuse cases to identify threats and choose proportionate controls early.', 'Threat modeling brings security decisions into architecture and change planning. We work with the teams who design and operate the system to identify valuable assets, entry points, trust boundaries and plausible abuse cases before they become expensive remediation work.', '[{"title":"System and data-flow mapping","body":"Record key components, identities, external dependencies, sensitive data and trust boundaries."},{"title":"Threat scenarios","body":"Identify likely attacker goals, misuse cases and paths through the architecture, based on the system''s actual context."},{"title":"Control recommendations","body":"Recommend preventive, detective and recovery controls proportionate to the risks and operating constraints."},{"title":"Action tracking","body":"Capture decisions, owners and follow-up items so the model informs implementation and future changes."}]'::jsonb, array(select jsonb_array_elements_text('["Security risks considered before implementation","Documented trust boundaries and attack paths","Controls connected to specific threats"]'::jsonb))::text[],
    '[{"question":"When should we do threat modeling?","answer":"Do it while a system or major change is being designed, and revisit it when architecture, data flows, trust boundaries or exposure change materially."},{"question":"Does threat modeling require a finished design?","answer":"No. An early model can be useful with a draft architecture. It helps teams identify decisions that should be made before implementation makes them costly to change."},{"question":"What does the team receive?","answer":"A system view with assets, trust boundaries, plausible threat scenarios, recommended controls and assigned follow-up actions."}]'::jsonb, null, '{"seed":203,"label":"Threat model","caption":"Architecture, trust boundaries and data flows are reviewed to identify attack paths and suitable controls."}'::jsonb,
    'Threat Modeling Services', 'Architecture-focused threat modeling for data flows, trust boundaries, attack scenarios and practical security controls.', 'published', null
  ),
(
    'cybersecurity', 'threat-analysis', 4, 'Threat Analysis', 'Turn suspicious signals into prioritized security action.',
    'Contextual analysis of security alerts, indicators and observed activity to establish likely impact, urgency and the next response step.', 'Threat analysis helps a team decide what an alert means for its own environment. We correlate available evidence with asset criticality, exposure and known activity, then provide a clear assessment of what is credible, what needs investigation and what action should happen next.', '[{"title":"Alert and indicator review","body":"Assess suspicious events, indicators and available telemetry against the assets and controls in scope."},{"title":"Context and impact analysis","body":"Correlate evidence with system criticality, exposure, identity activity and relevant threat context."},{"title":"Triage recommendations","body":"Separate likely false positives from activity that needs containment, investigation or escalation."},{"title":"Response notes","body":"Record evidence, decisions, next actions and escalation guidance for the operating team."}]'::jsonb, array(select jsonb_array_elements_text('["Prioritized alerts with operational context","Clear escalation and containment guidance","Recorded analysis for follow-up and review"]'::jsonb))::text[],
    '[{"question":"How is threat analysis different from threat modeling?","answer":"Threat modeling anticipates possible attacks against a system design. Threat analysis evaluates observed alerts, indicators or activity to determine what may be happening now and how to respond."},{"question":"Do you need a specific security platform?","answer":"No. The analysis uses the logs, alerts and evidence available from the client''s tools. We identify data gaps that limit confidence and can recommend how to improve visibility."},{"question":"Does threat analysis include incident response?","answer":"It includes triage and response recommendations. Containment, recovery and incident coordination can be agreed as additional response work depending on the situation."}]'::jsonb, null, '{"seed":204,"label":"Threat analysis","caption":"Security signals are correlated with asset context and exposure to guide investigation and response."}'::jsonb,
    'Threat Analysis Services', 'Contextual security alert and threat analysis with risk prioritization, triage guidance and response recommendations.', 'published', null
  ),
(
    'cloud-datacenter', 'cloud-ai-data-services', 1, 'Cloud AI & Data Services', 'Make cloud data useful, governed and ready to grow.',
    'Cloud data engineering, analytics and AI workload design with clear controls for access, data quality, security and ongoing operations.', 'We help teams shape cloud data platforms and AI workloads around a defined business use case. The work starts with data readiness and ownership, then covers architecture, integration, governance, deployment and the operating controls needed to keep the platform useful and supportable.', '[{"title":"Use-case and data readiness","body":"Clarify the decision or workflow to improve, identify relevant data sources, and assess quality, access, retention and ownership."},{"title":"Cloud data architecture","body":"Design ingestion, storage and processing paths that fit the required scale, latency, residency and security boundaries."},{"title":"Analytics and AI workloads","body":"Implement agreed analytics or AI capabilities with traceable inputs, validation and human review where decisions require it."},{"title":"Governance and operations","body":"Set access controls, logging, monitoring, cost visibility and ownership for the platform after launch."}]'::jsonb, array(select jsonb_array_elements_text('["A defined data path with named owners","Analytics built around agreed use cases and quality checks","AI workloads with access, review and operating controls"]'::jsonb))::text[],
    '[{"question":"What is included in cloud AI and data services?","answer":"Depending on scope, work can include data readiness, cloud architecture, ingestion pipelines, analytics, AI workload integration, governance and operational monitoring."},{"question":"Do we need to build a custom AI model?","answer":"Not always. We first evaluate whether existing services or models can meet the use case, data-handling rules and expected operating cost. Custom development is considered only when it is justified."},{"question":"How do you protect sensitive data?","answer":"Access, encryption, retention, logging and data residency are designed into the proposed platform. The exact controls are agreed against the data classification and applicable requirements."}]'::jsonb, '{"title":"From source data to governed insight","steps":[{"title":"Connect","description":"Map approved sources and owners."},{"title":"Govern","description":"Set access, quality and retention."},{"title":"Analyze","description":"Apply analytics or AI to a defined use."},{"title":"Operate","description":"Monitor outputs, access and cost."}],"image":"/site/infographics/cloud-ai-data-services.svg"}'::jsonb, '{"seed":301,"label":"Cloud AI and data","caption":"Governed data flows support analytics and AI workloads with clear ownership, access and review controls."}'::jsonb,
    'Cloud AI & Data Services', 'Cloud data engineering, analytics and AI workload services with governance, access controls and operational monitoring.', 'published', null
  ),
(
    'cloud-datacenter', 'managed-cloud-support-msp', 2, 'Managed Cloud Support Services (MSP)', 'Keep cloud operations owned, monitored and supportable.',
    'Ongoing cloud administration, monitoring, incident handling, security hygiene and service reporting under an agreed support scope.', 'A managed cloud service gives teams a defined operating path for the environment after deployment. We agree which subscriptions, workloads and controls are covered, then provide administration, monitoring, incident coordination and regular service evidence to the agreed coverage and response terms.', '[{"title":"Service onboarding","body":"Record accounts, subscriptions, owners, critical workloads, access paths, dependencies and support boundaries."},{"title":"Cloud administration","body":"Manage agreed configuration, identity, capacity, patch coordination and routine operational changes."},{"title":"Monitoring and incident response","body":"Review alerts against agreed severity, coordinate investigation and escalation, and record actions through closure."},{"title":"Service reporting","body":"Review availability signals, incidents, changes, backup status, risks and follow-up actions on an agreed cadence."}]'::jsonb, array(select jsonb_array_elements_text('["A named operating scope and escalation path","Consistent administration with recorded changes","Service reviews based on operating evidence"]'::jsonb))::text[],
    '[{"question":"What does a managed cloud support service cover?","answer":"The scope can include cloud account administration, monitoring, incident coordination, identity and access hygiene, backup checks, change records and service reporting. Coverage and response targets are agreed in writing."},{"question":"Can you support a cloud environment built by another provider?","answer":"Yes. We begin with a transition review to understand the tenant, workloads, access, monitoring and open risks before accepting the agreed operating scope."},{"question":"Do you provide 24/7 support?","answer":"Support hours and response commitments depend on the selected service agreement. We document the coverage, severity definitions and escalation contacts before service starts."}]'::jsonb, '{"title":"A managed cloud operating loop","steps":[{"title":"Discover","description":"Record workloads, owners and boundaries."},{"title":"Monitor","description":"Review health and agreed service signals."},{"title":"Respond","description":"Triage, act and escalate by severity."},{"title":"Report","description":"Review service evidence and open actions."}],"image":"/site/infographics/managed-cloud-support-msp.svg"}'::jsonb, '{"seed":302,"label":"Managed cloud operations","caption":"Cloud support follows an agreed path from monitoring and triage through action, escalation and service review."}'::jsonb,
    'Managed Cloud Support Services (MSP)', 'Managed cloud administration, monitoring, incident coordination and service reporting with agreed support coverage.', 'published', null
  ),
(
    'cloud-datacenter', 'cloud-cost-optimization', 3, 'Cloud Cost Optimization & Consulting', 'Align cloud spend with workloads and business priorities.',
    'Cloud cost visibility, workload reviews, right-sizing recommendations and governance practices based on actual usage and requirements.', 'Cloud cost optimization is an ongoing engineering and governance task, not a one-time promise of savings. We review billing and utilization signals alongside availability, performance, recovery and growth requirements, then prioritize changes that are safe to make and practical to measure.', '[{"title":"Cost and usage baseline","body":"Organize spend by account, service, environment or owner and identify gaps in tags, budgets and allocation."},{"title":"Workload and capacity review","body":"Compare resource sizing and utilization with performance, availability and recovery requirements."},{"title":"Optimization plan","body":"Prioritize right-sizing, scheduling, storage lifecycle and commitment options with risks and dependencies recorded."},{"title":"Governance and review","body":"Set budget alerts, ownership and a regular review cycle so changes can be checked against actual usage."}]'::jsonb, array(select jsonb_array_elements_text('["Spend linked to workloads and owners","Optimization actions ranked by impact and operational risk","Ongoing cost governance and review cadence"]'::jsonb))::text[],
    '[{"question":"Can you guarantee a specific percentage of savings?","answer":"No. Results depend on current architecture, usage patterns, commercial terms and service constraints. We establish a baseline and propose measurable changes rather than promise an unsupported percentage."},{"question":"Will cost changes affect performance or availability?","answer":"Recommendations are reviewed against workload requirements and change controls. Any action that could affect service is tested and scheduled with an agreed rollback position."},{"question":"Which cloud platforms can you review?","answer":"We can assess major public cloud and hybrid environments where billing and utilization data are available. The required access and data sources are agreed during scoping."}]'::jsonb, '{"title":"Optimize against actual usage","steps":[{"title":"Baseline","description":"Attribute spend and usage to owners."},{"title":"Analyze","description":"Compare capacity with workload needs."},{"title":"Adjust","description":"Prioritize safe, measurable changes."},{"title":"Review","description":"Check results and update budgets."}],"image":"/site/infographics/cloud-cost-optimization.svg"}'::jsonb, '{"seed":303,"label":"Cloud cost review","caption":"Usage and cost are evaluated together with performance, availability and recovery needs before changes are prioritized."}'::jsonb,
    'Cloud Cost Optimization & Consulting', 'Cloud cost and utilization reviews, right-sizing guidance, budget controls and ongoing optimization governance.', 'published', null
  ),
(
    'cloud-datacenter', 'cloud-disaster-recovery-business-continuity', 4, 'Cloud Disaster Recovery & Business Continuity', 'Know how critical services recover before an outage.',
    'Cloud recovery architecture, continuity planning, replication choices and practical recovery exercises tied to defined business objectives.', 'A cloud recovery plan is useful only when the business can execute and test it. We identify critical services, dependencies and recovery objectives, then design the appropriate backup or replication approach and rehearse the runbook so gaps are recorded before a real disruption.', '[{"title":"Business impact and recovery objectives","body":"Identify critical services, dependencies, acceptable data loss and recovery time targets with the business owners."},{"title":"Recovery architecture","body":"Select backup, replication and alternate-environment patterns according to risk, cost and service requirements."},{"title":"Runbooks and responsibilities","body":"Document decision points, access, escalation, restoration sequence and communications responsibilities."},{"title":"Recovery exercises","body":"Plan and conduct agreed tests, capture actual recovery evidence and track corrective actions."}]'::jsonb, array(select jsonb_array_elements_text('["Recovery objectives that reflect business priorities","Documented dependencies and recovery responsibilities","Test evidence and a tracked improvement plan"]'::jsonb))::text[],
    '[{"question":"What is the difference between disaster recovery and business continuity?","answer":"Disaster recovery focuses on restoring technology and data. Business continuity also covers people, processes, communications and alternate ways to deliver essential services during disruption."},{"question":"How often should recovery be tested?","answer":"The cadence should reflect service criticality, change frequency and business requirements. At minimum, tests should be repeated after material architecture changes and at the interval agreed with service owners."},{"question":"Can cloud replication replace backups?","answer":"No. Replication can copy corruption or deletion as well as good data. Recovery design normally combines protected backups with replication or alternate capacity where appropriate."}]'::jsonb, '{"title":"Plan, rehearse and improve recovery","steps":[{"title":"Define","description":"Set service priorities and recovery targets."},{"title":"Protect","description":"Choose backup and replication paths."},{"title":"Rehearse","description":"Test the runbook and record timings."},{"title":"Improve","description":"Close gaps and repeat after change."}],"image":"/site/infographics/cloud-disaster-recovery-business-continuity.svg"}'::jsonb, '{"seed":304,"label":"Cloud recovery planning","caption":"Recovery objectives, protected copies and rehearsed runbooks make continuity practical and testable."}'::jsonb,
    'Cloud Disaster Recovery & Business Continuity', 'Cloud recovery planning, backup and replication design, runbooks and tested business continuity exercises.', 'published', null
  ),
(
    'cloud-datacenter', 'cloud-monitoring-management', 5, 'Cloud Monitoring & Management', 'Turn cloud signals into clear operational action.',
    'Cloud resource health, performance, logs and alerts configured around service importance, ownership and practical response paths.', 'Cloud monitoring should show whether a service is healthy and help the right person decide what to do next. We identify meaningful signals, assign ownership, reduce noisy alerts and connect monitoring to response and service review rather than treating dashboards as the outcome.', '[{"title":"Service and resource inventory","body":"Map cloud resources to applications, owners, dependencies and service criticality."},{"title":"Metrics, logs and health checks","body":"Select signals for availability, capacity, performance and errors that are useful for the actual workload."},{"title":"Alert design and routing","body":"Set thresholds, severity, deduplication and destinations so actionable issues reach the right team."},{"title":"Operational review","body":"Review incidents, trends and monitoring gaps, then tune coverage as systems change."}]'::jsonb, array(select jsonb_array_elements_text('["Service health signals tied to owners","Alerts prioritized by operational impact","Monitoring coverage reviewed as architecture changes"]'::jsonb))::text[],
    '[{"question":"What should be monitored in a cloud environment?","answer":"Start with service availability, application errors, resource capacity, critical dependencies, security-relevant events and backup status. The exact signals depend on each workload and its service objectives."},{"question":"Can you reduce alert noise?","answer":"Yes. We review thresholds, duplicate events, ownership and escalation logic, then tune rules against observed behavior and the agreed response process."},{"question":"Do you provide 24/7 monitoring?","answer":"Monitoring and response coverage are distinct. We can configure continuous alerting and agree the operating hours, acknowledgement targets and escalation coverage in the service scope."}]'::jsonb, '{"title":"From telemetry to action","steps":[{"title":"Collect","description":"Gather useful health and performance signals."},{"title":"Correlate","description":"Connect alerts with services and owners."},{"title":"Route","description":"Send actionable events to responders."},{"title":"Tune","description":"Review noise, gaps and recurring issues."}],"image":"/site/infographics/cloud-monitoring-management.svg"}'::jsonb, '{"seed":305,"label":"Cloud monitoring","caption":"Metrics, logs and alerts are mapped to service owners and response paths, then tuned through operational review."}'::jsonb,
    'Cloud Monitoring & Management', 'Cloud health and performance monitoring, actionable alerting, resource administration and operational reviews.', 'published', null
  ),
(
    'cloud-datacenter', 'cloud-application-hosting', 6, 'Cloud Application Hosting', 'Host business applications with a clear operating model.',
    'Cloud environments for business applications, with deployment planning, identity, network, backup, monitoring and support responsibilities defined.', 'Application hosting begins with the workload, not the cloud service menu. We assess dependencies, performance needs, data location, availability and recovery requirements, then design and operate an appropriate hosting environment with clear handover and support boundaries.', '[{"title":"Workload and dependency review","body":"Map runtime, data, integrations, access, performance and continuity requirements before selecting a hosting pattern."},{"title":"Hosting environment design","body":"Plan accounts, networks, identity, compute, storage, security controls and capacity for the agreed application."},{"title":"Deployment and transition","body":"Coordinate release, validation, cutover and rollback steps with application and infrastructure owners."},{"title":"Operations and lifecycle","body":"Define monitoring, backup, patching, scaling, support and maintenance responsibilities after launch."}]'::jsonb, array(select jsonb_array_elements_text('["Hosting architecture tied to application needs","Controlled deployment with a rollback position","Clear ownership for ongoing application operations"]'::jsonb))::text[],
    '[{"question":"Can you host an existing application?","answer":"Yes, subject to a workload assessment. We review dependencies, software support, data, connectivity and recovery needs before recommending a migration or hosting plan."},{"question":"Can hosting include application support?","answer":"Infrastructure hosting and application-level support can be combined when the required responsibilities, access, response scope and vendor dependencies are agreed."},{"question":"How do you plan a hosting migration?","answer":"We map dependencies, prepare the environment, validate the application, schedule a controlled cutover and document the rollback path before moving production traffic."}]'::jsonb, '{"title":"Host the workload, not just the server","steps":[{"title":"Assess","description":"Map runtime, data and dependencies."},{"title":"Design","description":"Set identity, network and capacity."},{"title":"Deploy","description":"Validate release and rollback steps."},{"title":"Operate","description":"Monitor, protect and maintain service."}],"image":"/site/infographics/cloud-application-hosting.svg"}'::jsonb, '{"seed":306,"label":"Cloud application hosting","caption":"Application dependencies, environment design, release checks and operating responsibilities are planned together."}'::jsonb,
    'Cloud Application Hosting Services', 'Cloud application hosting with workload assessment, controlled deployment, security, monitoring and defined operations.', 'published', null
  ),
(
    'cloud-datacenter', 'cloud-devops-automation', 7, 'Cloud DevOps & Automation', 'Make cloud delivery repeatable, tested and observable.',
    'Cloud infrastructure automation and delivery pipelines that reduce manual release steps while keeping approvals, security checks and rollback visible.', 'DevOps and automation improve delivery when they make changes repeatable without hiding risk. We review the current release path, then implement suitable infrastructure-as-code, build and deployment workflows with access controls, validation, approvals and an agreed rollback method.', '[{"title":"Delivery workflow assessment","body":"Map source, environments, approvals, deployment steps, secrets and release dependencies."},{"title":"Infrastructure as code","body":"Represent agreed cloud configuration in reviewable, version-controlled templates or code."},{"title":"Build and release automation","body":"Automate selected build, test and deployment steps with controlled promotion between environments."},{"title":"Security and operations","body":"Add access boundaries, secret handling, change records, pipeline monitoring and failure recovery guidance."}]'::jsonb, array(select jsonb_array_elements_text('["Repeatable cloud configuration and releases","Review and approval points preserved in the pipeline","Clear failure and rollback procedures for deployments"]'::jsonb))::text[],
    '[{"question":"Do we need a full CI/CD platform to start?","answer":"No. We assess the existing repository, cloud platform and release process, then automate the highest-value steps using tools the team can maintain."},{"question":"Can infrastructure changes still require approval?","answer":"Yes. Code review, environment promotion and production approval can remain explicit controls within an automated workflow."},{"question":"What happens when a deployment fails?","answer":"The workflow should stop safely, retain logs and provide a tested rollback or recovery step appropriate to the application and infrastructure change."}]'::jsonb, '{"title":"A controlled cloud delivery pipeline","steps":[{"title":"Commit","description":"Review and version infrastructure changes."},{"title":"Build","description":"Validate code and run selected tests."},{"title":"Release","description":"Promote changes with clear approvals."},{"title":"Observe","description":"Track health and improve the workflow."}],"image":"/site/infographics/cloud-devops-automation.svg"}'::jsonb, '{"seed":307,"label":"Cloud DevOps pipeline","caption":"A controlled delivery path connects infrastructure code, tests, approvals, release and operational feedback."}'::jsonb,
    'Cloud DevOps & Automation Services', 'Cloud infrastructure-as-code, build and release automation with security checks, approvals and rollback procedures.', 'published', null
  ),
(
    'ai-automations', 'ai-chatbot-development', 1, 'AI ChatBot Development', 'Build useful conversations around your real processes.',
    'Custom AI chatbots for customer support, internal knowledge and guided workflows, with approved data sources, safe handoffs and measurable evaluation.', 'A useful chatbot needs more than a language model. We define the audience and supported tasks, connect approved knowledge, design clear boundaries and human escalation, then evaluate answers against realistic questions before release.', '[{"title":"Conversation and use-case design","body":"Map user intents, supported questions, unavailable answers and the points where a person must take over."},{"title":"Knowledge and system connections","body":"Connect approved documents or APIs with access controls, source attribution and a refresh process."},{"title":"Safety and handoff","body":"Set refusal behavior, sensitive-data boundaries, escalation paths, logging and feedback capture."},{"title":"Testing and launch","body":"Evaluate representative conversations, edge cases and response quality, then document ownership and ongoing review."}]'::jsonb, array(select jsonb_array_elements_text('["A chatbot scoped to specific user tasks","Responses grounded in approved knowledge sources","Clear escalation when the bot cannot safely answer"]'::jsonb))::text[],
    '[{"question":"Can the chatbot use our internal documents?","answer":"Yes, if the documents are approved for that use. We plan access, indexing, source attribution, update frequency and permission boundaries as part of the design."},{"question":"Will the chatbot always answer correctly?","answer":"No AI system can guarantee that. We test against agreed examples, show appropriate uncertainty, provide a human handoff and monitor feedback to improve the experience."},{"question":"Can you add the chatbot to our existing website or support portal?","answer":"Yes, subject to the platform and security requirements. We scope the integration, authentication, data exchange and operating ownership before implementation."}]'::jsonb, '{"title":"Design a grounded AI conversation","steps":[{"title":"Discover","description":"Define users, intents and boundaries."},{"title":"Connect","description":"Ground replies in approved knowledge."},{"title":"Evaluate","description":"Test answers and safe handoffs."},{"title":"Improve","description":"Review feedback and update sources."}],"image":"/site/infographics/ai-chatbot-development.svg"}'::jsonb, '{"seed":401,"label":"AI chatbot development","caption":"A purpose-built chatbot connects approved knowledge to a tested conversation, with a human handoff when needed."}'::jsonb,
    'AI ChatBot Development Services', 'Custom AI chatbot development with approved knowledge sources, safe escalation, evaluation and integration.', 'published', null
  ),
(
    'ai-automations', 'ai-callers-development', 2, 'AI Callers Development', 'Automate routine voice interactions with human oversight.',
    'Voice assistants for defined inbound and outbound tasks such as appointment coordination and service updates, designed around consent, disclosure and a clear transfer to staff.', 'Voice automation should make routine interactions easier without obscuring who is calling or removing access to a person. We define allowed call purposes and consent requirements, create the conversation flow, connect approved scheduling or service systems, and test interruptions, failed recognition and escalation before launch.', '[{"title":"Call purpose and consent rules","body":"Document permitted audiences, call timing, disclosures, opt-out handling, recording rules and escalation triggers."},{"title":"Voice conversation design","body":"Create concise prompts, turn-taking, confirmation steps and recovery behavior for misunderstood or incomplete responses."},{"title":"Telephony and system integration","body":"Connect approved calling infrastructure with scheduling, ticketing or customer systems using scoped data access."},{"title":"Quality and oversight","body":"Test realistic call scenarios, review call outcomes and provide staff transfer, audit and improvement processes."}]'::jsonb, array(select jsonb_array_elements_text('["Voice automation limited to agreed call tasks","Clear disclosure, consent and opt-out handling","A reliable route to a human agent"]'::jsonb))::text[],
    '[{"question":"What kinds of calls can an AI caller handle?","answer":"Typical scoped uses include appointment reminders, scheduling assistance and routine service updates. The purpose, audience, disclosures, consent and escalation rules are agreed before deployment."},{"question":"Can a caller transfer someone to a person?","answer":"Yes. Human transfer is part of the conversation design, with defined triggers such as a request for staff, uncertainty, a complaint or an out-of-scope question."},{"question":"Do you support call recording?","answer":"Recording is optional and subject to applicable consent and retention requirements. We define whether calls are recorded, how notice is provided, who can access recordings and when they are deleted."}]'::jsonb, '{"title":"A responsible AI voice interaction","steps":[{"title":"Authorize","description":"Set purpose, consent and disclosure."},{"title":"Engage","description":"Use clear prompts and confirmations."},{"title":"Resolve","description":"Complete the approved routine task."},{"title":"Transfer","description":"Escalate uncertainty to a person."}],"image":"/site/infographics/ai-callers-development.svg"}'::jsonb, '{"seed":402,"label":"AI voice caller development","caption":"A supervised voice workflow confirms intent, handles routine tasks and transfers uncertain calls to a person."}'::jsonb,
    'AI Callers Development Services', 'Responsible AI voice caller development for defined service workflows, with consent, opt-out and human escalation controls.', 'published', null
  ),
(
    'ai-automations', 'llm-development', 3, 'LLM Development', 'Engineer language-model solutions against clear evaluation criteria.',
    'Language-model application design, retrieval-augmented generation, prompt and tool orchestration, evaluation and deployment controls aligned to your data and product needs.', 'We help teams choose and engineer a language-model approach for a defined product or workflow. That may mean integrating a managed model, grounding responses in private content, connecting tools, or adapting a model when evidence supports it. Quality, privacy, latency, cost and operational ownership are evaluated before production use.', '[{"title":"Model and use-case assessment","body":"Compare candidate approaches against task quality, data boundaries, latency, cost, hosting and ongoing support needs."},{"title":"Retrieval and orchestration","body":"Build document retrieval, structured tool use and response workflows with permission checks and traceable sources."},{"title":"Evaluation and guardrails","body":"Create representative test sets and measure factuality, relevance, refusal behavior, robustness and regression over time."},{"title":"Deployment and monitoring","body":"Plan versioning, observability, access, fallback behavior and a review path for model or prompt changes."}]'::jsonb, array(select jsonb_array_elements_text('["A model approach justified by task and constraints","Repeatable evaluation before and after changes","Production controls for data, access and model behavior"]'::jsonb))::text[],
    '[{"question":"Does LLM development mean training a model from scratch?","answer":"Usually not. We first assess managed models, retrieval and prompt or tool orchestration. Fine-tuning or custom training is considered only when it is appropriate for the data, task and operating budget."},{"question":"Can a language model work with private company data?","answer":"Yes, with an architecture that enforces access controls and approved data handling. We evaluate provider terms, data retention, permissions, retrieval and logging as part of the design."},{"question":"How do you measure model quality?","answer":"We agree a representative evaluation set and assess task-specific measures such as relevance, groundedness, correct tool use, refusal behavior, latency and cost."}]'::jsonb, '{"title":"Engineer an LLM solution end to end","steps":[{"title":"Select","description":"Match a model to task and constraints."},{"title":"Ground","description":"Connect controlled data and tools."},{"title":"Evaluate","description":"Measure quality, risk and cost."},{"title":"Deploy","description":"Monitor versions and live behavior."}],"image":"/site/infographics/llm-development.svg"}'::jsonb, '{"seed":403,"label":"LLM engineering","caption":"Model selection, retrieval, evaluation and monitoring form a repeatable engineering lifecycle for language-model applications."}'::jsonb,
    'LLM Development Services', 'LLM application engineering, retrieval, orchestration, evaluation and production controls for business use cases.', 'published', null
  ),
(
    'ai-automations', 'it-infrastructure-ai-automations', 4, 'IT Infrastructure AI Automations', 'Bring controlled automation to infrastructure operations.',
    'AI-assisted incident triage, operational knowledge lookup and approved infrastructure workflows that keep change controls, engineer review and audit records in place.', 'Infrastructure automation must not turn a suggested action into an uncontrolled production change. We connect approved telemetry and runbooks to triage or orchestration workflows, define which actions can run automatically, and preserve review, approval, rollback and audit steps for consequential changes.', '[{"title":"Operations workflow assessment","body":"Map alert sources, runbooks, access boundaries, repeat incidents and the operational decisions that can be safely assisted."},{"title":"Triage and knowledge workflows","body":"Summarize incident context, retrieve relevant procedures and route events to the correct team with source links."},{"title":"Approved remediation automation","body":"Automate low-risk, reversible tasks where authorized; require engineer approval for production-impacting changes."},{"title":"Audit and rollback controls","body":"Record inputs, decisions, approvals and outcomes, and define rollback and disable procedures for every automation."}]'::jsonb, array(select jsonb_array_elements_text('["Faster context gathering for infrastructure incidents","Automation limited by risk and explicit approval rules","Auditable actions with a rollback and disable path"]'::jsonb))::text[],
    '[{"question":"Can AI make infrastructure changes without an engineer?","answer":"Only narrowly scoped, low-risk actions should be considered for unattended execution. Production-impacting or irreversible changes require explicit authorization and review controls."},{"question":"Can this work with our existing monitoring and ticketing tools?","answer":"Often, if supported APIs or event interfaces are available. We review access and integration constraints before designing the workflow."},{"question":"How is an automated action audited?","answer":"The workflow can record its triggering signal, supporting context, policy decision, approvals, action result and rollback status in the agreed operations record."}]'::jsonb, '{"title":"Keep infrastructure automation under control","steps":[{"title":"Detect","description":"Collect signals from approved systems."},{"title":"Triage","description":"Add context from trusted runbooks."},{"title":"Approve","description":"Apply risk-based human review."},{"title":"Record","description":"Log actions, outcomes and rollback."}],"image":"/site/infographics/it-infrastructure-ai-automations.svg"}'::jsonb, '{"seed":404,"label":"Infrastructure AI automation","caption":"Operational signals and runbooks guide an approved response, with engineer review and an auditable rollback path."}'::jsonb,
    'IT Infrastructure AI Automation Services', 'AI-assisted IT operations automation for incident triage and approved remediation with human review and audit controls.', 'published', null
  ),
(
    'application-development', 'web-application-development', 1, 'Web Application Development', 'Build secure web products around the way people work.',
    'Custom browser-based applications, internal portals and workflow tools with accessible interfaces, tested integrations and a supportable architecture.', 'Web applications combine user experience, business logic, data and integrations into a product people rely on every day. We define roles and workflows first, then design the application architecture, build and test the interface and services, and prepare an accountable release and handover.', '[{"title":"Product and workflow discovery","body":"Define user roles, key journeys, permissions, data needs, integrations and measurable acceptance criteria."},{"title":"Application architecture and interface","body":"Design browser experience, application services and data boundaries for usability, accessibility and future change."},{"title":"Implementation and integration","body":"Develop features and connect approved APIs or enterprise systems with validation and resilient error handling."},{"title":"Testing, release and handover","body":"Test critical journeys and access controls, prepare deployment and rollback guidance, and deliver source and technical notes."}]'::jsonb, array(select jsonb_array_elements_text('["A browser application tailored to defined workflows","Tested integrations and role-aware access","A controlled release with clear support ownership"]'::jsonb))::text[],
    '[{"question":"What is the difference between a website and a web application?","answer":"A website primarily publishes content and information. A web application enables users to sign in, enter or manage data, and complete interactive workflows. Some products combine both."},{"question":"Can you modernize an existing web application?","answer":"Yes. We assess the codebase, hosting, dependencies, security and user workflows, then scope an incremental improvement or rebuild based on risk and business priorities."},{"question":"Do you provide the source code?","answer":"The agreed handover includes source code and documentation, with repository ownership and any third-party dependencies clarified in the project scope."}]'::jsonb, '{"title":"From workflow to working web app","steps":[{"title":"Discover","description":"Map users, roles and key journeys."},{"title":"Design","description":"Plan interface, services and data."},{"title":"Build","description":"Implement and test features."},{"title":"Release","description":"Deploy, hand over and support."}],"image":"/site/infographics/web-application-development.svg"}'::jsonb, '{"seed":405,"label":"Web application development","caption":"User workflows, application services, integration tests and a managed release connect into a maintainable web product."}'::jsonb,
    'Web Application Development Services', 'Custom web application development for portals and workflows, with secure integrations, testing and handover.', 'published', null
  ),
(
    'application-development', 'website-development', 2, 'Website Development', 'Create a clear, fast and maintainable web presence.',
    'Responsive business websites with content structure, accessible design, search fundamentals, analytics readiness and a practical editing and maintenance handover.', 'A business website should make it easy to understand what you offer and take the next step. We shape the site structure and content model, design responsive page templates, implement performance and accessibility practices, and prepare the publishing and maintenance workflow for your team.', '[{"title":"Content and site architecture","body":"Organize audiences, pages, navigation and calls to action around the information visitors need."},{"title":"Responsive design and implementation","body":"Build consistent page templates that work across screen sizes and support accessible interaction."},{"title":"Search and performance fundamentals","body":"Configure page metadata, semantic structure, image optimization, redirects and technical performance checks."},{"title":"Publishing and handover","body":"Set up the agreed content editing workflow, analytics integration and maintenance documentation."}]'::jsonb, array(select jsonb_array_elements_text('["A coherent and easy-to-navigate website","Responsive pages with search and accessibility basics","A documented content and upkeep workflow"]'::jsonb))::text[],
    '[{"question":"Can we update website content ourselves?","answer":"Yes. The content workflow can use an agreed CMS or a managed publishing process. Editing roles and training are included in the handover plan."},{"question":"Does website development include SEO?","answer":"We implement technical and on-page foundations such as metadata, semantic page structure, redirects and performance. Search visibility also depends on ongoing content and external factors."},{"question":"Can you redesign an existing website without losing its search pages?","answer":"We inventory current routes and metadata, map redirects where URLs change and validate key pages during launch to reduce avoidable search disruption."}]'::jsonb, '{"title":"Plan and launch a business website","steps":[{"title":"Plan","description":"Set audiences, content and navigation."},{"title":"Design","description":"Shape responsive page templates."},{"title":"Develop","description":"Build accessible, fast pages."},{"title":"Publish","description":"Launch, measure and maintain."}],"image":"/site/infographics/website-development.svg"}'::jsonb, '{"seed":406,"label":"Website development","caption":"A content-led website moves from audience and structure through responsive design, implementation and publishing."}'::jsonb,
    'Website Development Services', 'Responsive business website design and development with content structure, accessibility, performance and handover.', 'published', null
  ),
(
    'application-development', 'mobile-application-development', 3, 'Mobile Application Development', 'Put useful workflows in the hands of your mobile users.',
    'Mobile app product design and engineering for iOS, Android or cross-platform delivery, including API integration, device testing and release planning.', 'A mobile application succeeds when it fits the user, the device and the operating environment. We define the core journeys and offline or notification needs, choose an appropriate native or cross-platform approach, build against secure services and test across representative devices before release.', '[{"title":"Mobile product discovery","body":"Define user journeys, device capabilities, accessibility, offline behavior, permissions and release requirements."},{"title":"Platform and interface design","body":"Select native or cross-platform architecture and design touch-first interactions for the supported devices."},{"title":"Application and API engineering","body":"Build app features, connect secure backend APIs and manage authentication, errors and data synchronization."},{"title":"Device testing and store release","body":"Test supported device and OS combinations, prepare release assets and document update and support responsibilities."}]'::jsonb, array(select jsonb_array_elements_text('["A mobile experience designed for real device use","Secure integration with agreed application services","Tested builds and a documented release process"]'::jsonb))::text[],
    '[{"question":"Do you build for both iOS and Android?","answer":"Yes. We choose native or cross-platform implementation based on device features, experience requirements, support needs and the agreed budget."},{"question":"Can the mobile app work offline?","answer":"Offline access can be designed for selected workflows. We define what can be stored locally, how data synchronizes and how conflicts or stale data are handled."},{"question":"Do you publish the app to the app stores?","answer":"We can prepare and support release submissions, subject to the client''s developer accounts, store policies, privacy disclosures and approval process."}]'::jsonb, '{"title":"Design, build and ship a mobile app","steps":[{"title":"Discover","description":"Define journeys and device needs."},{"title":"Design","description":"Create touch-first interfaces."},{"title":"Develop","description":"Build app features and secure APIs."},{"title":"Validate","description":"Test devices and prepare release."}],"image":"/site/infographics/mobile-application-development.svg"}'::jsonb, '{"seed":407,"label":"Mobile application development","caption":"Mobile product planning, touch-first design, API engineering and device testing lead to a controlled app release."}'::jsonb,
    'Mobile Application Development Services', 'Mobile app design and development for iOS and Android with secure APIs, device testing and release support.', 'published', null
  );

    alter table public.sub_services enable trigger c_audit;
  end if;
end $$;

do $$
begin
  if not exists (select 1 from public.blog_posts) then
    alter table public.blog_posts disable trigger c_audit;

    insert into public.blog_posts
      (slug, title, excerpt, category, reading_minutes, body, figure_seed, related_services,
       seo_title, seo_description, status, published_at)
    values
(
    'vulnerability-scan-or-penetration-test', 'Vulnerability scan or penetration test: which do you need?', 'A scan lists the known weaknesses across your systems. A penetration test shows what someone could actually do with them. Many organisations need both, at different points.', 'Cybersecurity', null,
    '[{"heading":"What a vulnerability scan does","paragraphs":["A vulnerability scan is automated. It checks your systems against a database of known weaknesses, such as missing patches, outdated software and risky settings, and produces a list. It is quick and repeatable, so it can run every month and after any significant change.","Its limits matter as much as its strengths. A scan reports what it recognises. It does not decide which findings matter in your environment, and it cannot show how several small weaknesses combine into a serious one."]},{"heading":"What a penetration test adds","paragraphs":["A penetration test is carried out by a person, inside an agreed scope and time window, who tries to get past your defences the way an attacker would. Its value is in the chain: an exposed service, a reused password and a flat network can add up to access nobody expected.","Because it relies on skilled people, it is done less often: before a major release, after a significant change to the environment, or when a customer or regulator expects independent testing."]},{"heading":"How to choose","paragraphs":["If you have never measured your exposure, start with a scan. It sets a baseline and clears the obvious issues before anyone is paid to find them the hard way. If the basics are under control and the question is whether your defences hold against a determined attempt, that is the case for a test.","Either way, agree the scope in writing first: which systems, which techniques, what is off limits and who needs to know. Testing live systems without that agreement is a risk in itself."]},{"heading":"Make the findings count","paragraphs":["A report only helps if every finding has an owner and a date. Track fixes like any other change, re-test the important ones, and keep the previous report so the next one shows whether things have improved."]}]'::jsonb, 201, '[{"label":"Vulnerability assessment","href":"/services/cybersecurity/vulnerability-assessment"},{"label":"Penetration testing","href":"/services/cybersecurity/penetration-testing"}]'::jsonb,
    'Vulnerability scan or penetration test?', 'What a vulnerability scan and a penetration test each do, when to use which, and how to turn the findings into fixes that actually happen.', 'published', '2026-11-10T00:00:00+05:30'
  ),
(
    'before-you-automate-with-ai-choose-the-process', 'Before you automate with AI, choose the process first', 'AI projects often stall on scope rather than technology. Choosing one well-understood process, with a clear handoff to people, decides whether the rest works.', 'AI & automation', null,
    '[{"heading":"Start with a process, not a tool","paragraphs":["\"We should use AI\" is not a requirement. A requirement sounds like this: customers keep asking the same twenty questions, and the answers are scattered across three documents. Start from work people already do repeatedly, where the inputs and the expected result are understood.","Good first candidates are frequent, rule-based and forgiving when they go wrong: drafting a first reply, routing a request to the right team, summarising a long thread. Poor first candidates are rare, high-stakes, or depend on judgement nobody has written down."]},{"heading":"Map the exceptions before you build","paragraphs":["The ordinary case is straightforward. The work is in the exceptions: the unusual request, the missing record, the upset customer. List them with the people who handle them today, and decide what the automation does when it meets one.","The safest default is a handoff. The system recognises that it is out of its depth and passes the case to a person, with the context attached so nobody has to ask the customer again."]},{"heading":"Decide how you will know it works","paragraphs":["Choose the measures before the build: time to first response, the share of requests resolved without a person, corrections made by staff. Record today''s figure first, so that any later claim of improvement has something to be compared with.","Then review a sample of real outputs on a schedule. Automated systems tend to drift quietly when products, prices or policies change, and a regular review is how you notice."]},{"heading":"Keep the first release small","paragraphs":["Launch for one process, one channel and one team. A narrow release is easier to test, easier to explain to staff and easier to switch off if it misbehaves. Widen it only after the measures and the handoffs have held up in daily use."]}]'::jsonb, 19, '[{"label":"AI ChatBot Development","href":"/services/ai-automations/ai-chatbot-development"},{"label":"LLM Development","href":"/services/ai-automations/llm-development"}]'::jsonb,
    'Before you automate with AI, choose the process', 'How to pick a first process for AI automation, plan for exceptions and handoffs, and decide in advance how you will measure whether it works.', 'published', '2026-11-10T00:00:00+05:30'
  ),
(
    'website-web-app-or-mobile-app-scoping-checklist', 'Website, web app or mobile app? A scoping checklist', 'The right shape for a digital product follows from who uses it, what they need to do and what it has to connect to, not from what is fashionable.', 'Application development', null,
    '[{"heading":"Start with what people need to do","paragraphs":["A website mostly informs: people read, compare and get in touch. A web application lets signed-in users do work, such as submitting requests, managing records or seeing their own data. A mobile app earns its extra cost when people need something the browser cannot do well.","Write down the three most important things a user must be able to do. If all three are \"read about us\" and \"contact us\", you are describing a website."]},{"heading":"Check the data and the connections","paragraphs":["Much of the cost sits behind the screen: where the data lives, who may see which part of it, and which existing systems the product must talk to, such as accounting, inventory or a customer database. List those connections early, along with the person who owns each system."]},{"heading":"Decide whether a mobile app earns its place","paragraphs":["Offline use, push notifications, camera or barcode scanning and background location are the usual reasons. Without one of them, a well-built web application that works properly on a phone is often the quicker and cheaper route, and it can become an app later if the need appears."]},{"heading":"Plan for after launch","paragraphs":["Someone has to host it, patch it, back it up and fix it. Decide who, and what that costs each year, before the build starts. A product with no owner after launch tends to become a security and reliability liability."]}]'::jsonb, 20, '[{"label":"Web Application Development","href":"/services/application-development/web-application-development"},{"label":"Mobile Application Development","href":"/services/application-development/mobile-application-development"}]'::jsonb,
    'Website, web app or mobile app? A scoping checklist', 'A short checklist for choosing between a website, a web application and a mobile app, covering users, data, integrations and who looks after it after launch.', 'published', '2026-11-10T00:00:00+05:30'
  );

    alter table public.blog_posts enable trigger c_audit;
  end if;
end $$;

do $$
begin
  if not exists (select 1 from public.case_studies) then
    alter table public.case_studies disable trigger c_audit;

    insert into public.case_studies
      (slug, title, sector, kind, client_name, client_approved, situation, work, result, services,
       sort_order, seo_title, seo_description, status, published_at)
    values
(
    'taking-over-an-undocumented-server-estate', 'Taking over an undocumented server estate', 'Professional services', 'representative', null, false,
    'A firm had servers installed over several years by different suppliers. Documentation was partial, backup jobs existed but had not been restored, and no one could describe the dependency between the file services and the line-of-business application.', array(select jsonb_array_elements_text('["Recorded the estate, including the undocumented virtual hosts and storage paths.","Verified backup integrity and ran a restore test into an isolated environment.","Documented the dependency map and the access model.","Moved monitoring and patching into a defined operating service."]'::jsonb))::text[], 'The estate became supportable by someone other than the original installer, with a verified restore and a current record.', array(select jsonb_array_elements_text('["it-infrastructure","managed-it"]'::jsonb))::text[],
    1, 'Taking over an undocumented server estate', 'A representative engagement: recording an undocumented server estate, proving the backups restore and moving it into a defined operating service.', 'published', null
  ),
(
    'separating-plant-and-office-networks', 'Separating plant and office networks', 'Manufacturing', 'representative', null, false,
    'Production equipment and corporate systems shared a flat network. A single compromised office endpoint could reach the plant floor, and change windows for either side were coordinated informally.', array(select jsonb_array_elements_text('["Mapped the traffic paths between plant equipment, servers and office users.","Designed segmentation with documented rules and a phased cutover.","Applied firewall changes with a rollback position for each phase.","Recorded the resulting topology and change process."]'::jsonb))::text[], 'Plant and office traffic follow documented paths, with changes coordinated through a single record.', array(select jsonb_array_elements_text('["network-engineering","cybersecurity"]'::jsonb))::text[],
    2, 'Separating plant and office networks', 'A representative engagement: separating a flat plant and office network with documented rules, a phased cutover and a rollback for each phase.', 'published', null
  ),
(
    'making-recovery-a-tested-capability', 'Making recovery a tested capability', 'Healthcare', 'representative', null, false,
    'A clinical environment had nightly backups and an assumed recovery time. The backup product reported success, but no restore had been attempted and the dependency on directory services was unclear.', array(select jsonb_array_elements_text('["Defined recovery point and recovery time expectations per system.","Confirmed an off-site copy existed and was independent of the primary storage.","Tested restores for the clinical application and its directory dependencies.","Recorded actual recovery times and the sequence for restoring service."]'::jsonb))::text[], 'Recovery expectations are now based on measured restores rather than on backup job status.', array(select jsonb_array_elements_text('["cloud-datacenter","managed-it"]'::jsonb))::text[],
    3, 'Making recovery a tested capability', 'A representative engagement: replacing an assumed recovery time with measured restore tests for a clinical application and its directory dependencies.', 'published', null
  );

    alter table public.case_studies enable trigger c_audit;
  end if;
end $$;
